<script setup lang="ts">
import { TALENTS, talentCost } from '../config/talent'
import { useGameStore } from '../stores/game'
import type { TalentKey } from '../types/game'
const store=useGameStore();const keys=Object.keys(TALENTS) as TalentKey[]
function effect(key:TalentKey,level:number){if(key==='luck')return `中奖概率 +${level}%`;if(key==='wealth')return `奖金 +${level*5}%`;if(key==='efficiency')return `刮奖时间减少 ${Math.min(80,level*5)}%`;if(key==='device')return `验票时间减少 ${Math.min(80,level*10)}%`;return level>=8?'完整自动化生产线':level>=5?'解锁自动购票':level>=3?'解锁自动刮奖':level>=2?'解锁自动领取':level>=1?'解锁自动提交':'逐步解锁自动化能力'}
</script>
<template><view class="page"><view class="page-heading"><view><text class="eyebrow">TALENT TREE</text><text>天赋研究所</text><view>分配天赋点，打造属于你的幸运经营策略。</view></view><view class="talent-points">✨ <text>{{store.game.player.talentPoints}}</text><text>可用天赋点</text></view></view><view class="talent-grid"><view v-for="key in keys" :key="key" class="panel talent-card"><view class="talent-top"><text class="talent-icon">{{TALENTS[key].icon}}</text><text class="level-tag">LV. {{store.game.talents[key]}} / {{TALENTS[key].maxLevel}}</text></view><text>{{TALENTS[key].name}}系</text><view>{{TALENTS[key].description}}</view><view class="talent-effect"><text>当前效果</text><text>{{effect(key,store.game.talents[key])}}</text></view><view class="talent-effect next"><text>下一级效果</text><text>{{effect(key,Math.min(TALENTS[key].maxLevel,store.game.talents[key]+1))}}</text></view><view class="talent-bottom"><text>🪙 {{talentCost(key,store.game.talents[key]).toLocaleString()}}</text><button class="btn primary" :disabled="store.game.talents[key]>=TALENTS[key].maxLevel||store.game.player.talentPoints<1||store.game.coins<talentCost(key,store.game.talents[key])" @tap="store.upgradeTalent(key)">升级 · 1 点</button></view></view></view><view class="reset-row"><view><text>重新规划天赋</text><text>重置后返还所有天赋点，不返还升级消耗的金币。</text></view><button class="btn secondary" @tap="store.resetTalents()">重置天赋</button></view></view></template>